def select_neighbor(archive: List[Tuple[np.ndarray, Tuple[float, float]]], weight_lst: np.ndarray, value1_lst: np.ndarray, value2_lst: np.ndarray, capacity: float) -> np.ndarray:
    """
    Select a promising solution from the archive and generate a neighbor solution from it.

    Args:
    archive: List of (solution, objective) pairs. Each solution is a binary numpy array (0/1) of item selections.
             Each objective is a tuple of two float values (total value1, total value2).
    weight_lst: Numpy array of shape (N, ), item weights.
    value1_lst: Numpy array of shape (N, ), item values for objective 1.
    value2_lst: Numpy array of shape (N, ), item values for objective 2.
    capacity: Maximum allowed total weight.

    Returns:
    A new neighbor solution (numpy array).
    """
    if not archive:
        return np.zeros_like(weight_lst, dtype=int)

    # Select a solution with high potential (high diversity and marginal utility)
    selected_idx = random.randint(0, len(archive) - 1)
    base_solution = archive[selected_idx][0].copy()
    current_weight = np.sum(weight_lst[base_solution == 1])
    new_solution = base_solution.copy()
    num_items = len(weight_lst)

    # Step 1: Probabilistic flip based on utility
    utility = (value1_lst + value2_lst) / (weight_lst + 1e-6)
    for i in range(num_items):
        if random.random() < 0.5 * (1 - base_solution[i]) + 0.3 * utility[i] / np.max(utility):
            if new_solution[i] == 1:
                if current_weight - weight_lst[i] >= 0:
                    new_solution[i] = 0
                    current_weight -= weight_lst[i]
            else:
                if current_weight + weight_lst[i] <= capacity:
                    new_solution[i] = 1
                    current_weight += weight_lst[i]

    # Step 2: Weighted random swap
    if num_items >= 2 and random.random() < 0.4:
        i, j = random.sample(range(num_items), 2)
        if new_solution[i] != new_solution[j]:
            delta_weight = (weight_lst[j] - weight_lst[i]) if new_solution[i] == 1 else (weight_lst[i] - weight_lst[j])
            if current_weight + delta_weight <= capacity:
                new_solution[i], new_solution[j] = new_solution[j], new_solution[i]

    # Step 3: Greedy marginal-gain insertion
    if current_weight < capacity:
        remaining_capacity = capacity - current_weight
        marginal_gains = (value1_lst + value2_lst) / (weight_lst + 1e-6)
        sorted_indices = np.argsort(marginal_gains)[::-1]
        for idx in sorted_indices:
            if new_solution[idx] == 0 and weight_lst[idx] <= remaining_capacity:
                new_solution[idx] = 1
                remaining_capacity -= weight_lst[idx]
                if remaining_capacity <= 0:
                    break

    # Step 4: Adaptive utility-based replacement
    if random.random() < 0.2:
        utility = (value1_lst + value2_lst) / (weight_lst + 1e-6)
        sorted_indices = np.argsort(utility * new_solution)[::-1]
        for idx in sorted_indices:
            if new_solution[idx] == 1 and current_weight - weight_lst[idx] >= 0:
                new_solution[idx] = 0
                current_weight -= weight_lst[idx]
                break

    return new_solution

def select_neighbor(archive: List[Tuple[np.ndarray, Tuple[float, float]]], weight_lst: np.ndarray, value1_lst: np.ndarray, value2_lst: np.ndarray, capacity: float) -> np.ndarray:
    """
    Select a promising solution from the archive and generate a neighbor solution from it.

    Args:
    archive: List of (solution, objective) pairs. Each solution is a binary numpy array (0/1) of item selections.
             Each objective is a tuple of two float values (total value1, total value2).
    weight_lst: Numpy array of shape (N, ), item weights.
    value1_lst: Numpy array of shape (N, ), item values for objective 1.
    value2_lst: Numpy array of shape (N, ), item values for objective 2.
    capacity: Maximum allowed total weight.

    Returns:
    A new neighbor solution (numpy array).
    """
    if not archive:
        return np.zeros_like(weight_lst, dtype=int)

    # Select a solution with high potential using weighted random choice
    weights = [sum(archive[i][1]) for i in range(len(archive))]
    selected_idx = random.choices(range(len(archive)), weights=weights, k=1)[0]
    base_solution = archive[selected_idx][0].copy()
    current_weight = np.sum(weight_lst[base_solution == 1])

    new_solution = base_solution.copy()
    num_items = len(weight_lst)

    # Step 1: Dynamic flip based on marginal utility
    for i in range(num_items):
        if new_solution[i] == 1:
            utility = (value1_lst[i] + value2_lst[i]) / weight_lst[i]
            flip_prob = 0.1 + 0.9 * (1 - utility / max(utility, 1))
            if random.random() < flip_prob and current_weight - weight_lst[i] >= 0:
                new_solution[i] = 0
                current_weight -= weight_lst[i]
        else:
            if current_weight + weight_lst[i] <= capacity:
                utility = (value1_lst[i] + value2_lst[i]) / weight_lst[i]
                flip_prob = 0.1 + 0.9 * (utility / max(utility, 1))
                if random.random() < flip_prob:
                    new_solution[i] = 1
                    current_weight += weight_lst[i]

    # Step 2: Swap with utility-based probability
    if num_items >= 2:
        i, j = random.sample(range(num_items), 2)
        if new_solution[i] != new_solution[j]:
            utility_i = (value1_lst[i] + value2_lst[i]) / weight_lst[i]
            utility_j = (value1_lst[j] + value2_lst[j]) / weight_lst[j]
            swap_prob = min(0.5, 0.1 + 0.4 * (utility_i - utility_j))
            if random.random() < swap_prob:
                if new_solution[i] == 1 and new_solution[j] == 0:
                    if current_weight - weight_lst[i] + weight_lst[j] <= capacity:
                        new_solution[i], new_solution[j] = new_solution[j], new_solution[i]
                elif new_solution[i] == 0 and new_solution[j] == 1:
                    if current_weight + weight_lst[i] - weight_lst[j] <= capacity:
                        new_solution[i], new_solution[j] = new_solution[j], new_solution[i]

    # Step 3: Insertion with utility-based probability
    if current_weight < capacity:
        candidates = [i for i in range(num_items) if new_solution[i] == 0 and weight_lst[i] <= (capacity - current_weight)]
        if candidates:
            utilities = [(value1_lst[i] + value2_lst[i]) / weight_lst[i] for i in candidates]
            chosen = random.choices(candidates, weights=utilities, k=1)[0]
            new_solution[chosen] = 1

    return new_solution

def select_neighbor(archive: List[Tuple[np.ndarray, Tuple[float, float]]], weight_lst: np.ndarray, value1_lst: np.ndarray, value2_lst: np.ndarray, capacity: float) -> np.ndarray:
    """
    Select a promising solution from the archive and generate a neighbor solution from it.

    Args:
    archive: List of (solution, objective) pairs. Each solution is a binary numpy array (0/1) of item selections.
             Each objective is a tuple of two float values (total value1, total value2).
    weight_lst: Numpy array of shape (N, ), item weights.
    value1_lst: Numpy array of shape (N, ), item values for objective 1.
    value2_lst: Numpy array of shape (N, ), item values for objective 2.
    capacity: Maximum allowed total weight.

    Returns:
    A new neighbor solution (numpy array).
    """
    if not archive:
        return np.zeros_like(weight_lst, dtype=int)

    # Select solution with high marginal utility (highest value ratio in either objective)
    selected_idx = np.argmax([(v1 + v2) / (w + 1e-6) for _, (v1, v2), w in
                             [(s, obj, np.sum(weight_lst[s == 1])) for s, obj in archive]])
    base_solution = archive[selected_idx][0].copy()
    current_weight = np.sum(weight_lst[base_solution == 1])

    new_solution = base_solution.copy()
    num_items = len(weight_lst)

    # Step 1: Probabilistic flip with value-weighted probability
    for i in range(num_items):
        if random.random() < 0.4 * (value1_lst[i] + value2_lst[i]) / (np.max(value1_lst) + np.max(value2_lst)):
            if new_solution[i] == 1:
                if current_weight - weight_lst[i] >= 0:
                    new_solution[i] = 0
                    current_weight -= weight_lst[i]
            else:
                if current_weight + weight_lst[i] <= capacity:
                    new_solution[i] = 1
                    current_weight += weight_lst[i]

    # Step 2: Guided swap based on value ratio
    if num_items >= 2:
        i, j = random.sample(range(num_items), 2)
        if new_solution[i] != new_solution[j]:
            ratio_i = (value1_lst[i] + value2_lst[i]) / weight_lst[i]
            ratio_j = (value1_lst[j] + value2_lst[j]) / weight_lst[j]
            if (new_solution[i] == 1 and ratio_i < ratio_j) or (new_solution[j] == 1 and ratio_j < ratio_i):
                if new_solution[i] == 1 and new_solution[j] == 0:
                    if current_weight - weight_lst[i] + weight_lst[j] <= capacity:
                        new_solution[i], new_solution[j] = new_solution[j], new_solution[i]
