    max_value1 = max(value1_lst) if max(value1_lst) > 0 else 1
    max_value2 = max(value2_lst) if max(value2_lst) > 0 else 1
    normalized_value1 = value1_lst / max_value1
    normalized_value2 = value2_lst / max_value2
    utilities = (normalized_value1 + normalized_value2) / weight_lst

    # Step 1: Dynamic flip based on marginal utility
    for i in range(num_items):
        if new_solution[i] == 1:
            flip_prob = 0.1 + 0.9 * (1 - utilities[i] / max(utilities))
            if random.random() < flip_prob and current_weight - weight_lst[i] >= 0:
