    max_score = -1
    selected_solution = None
    for sol, obj in archive:
        combined_value = obj[0] * 0.7 + obj[1] * 0.3  # Weighted combination of objectives
        current_weight = np.sum(weight_lst[sol == 1])
        score = combined_value / (current_weight + 1e-6) * 1.5  # Increased weight for combined value
        if score > max_score:
            max_score = score
            selected_solution = sol.copy()

    if selected_solution is None:
        selected_solution = archive[0][0].copy()

    new_solution = selected_solution.copy()
    current_weight = np.sum(weight_lst[new_solution == 1])
    n_items = len(weight_lst)

    # Stage 1: Probabilistic item replacements with adaptive objective weights
    obj_ratio = np.sum(new_solution * value1_lst) / (np.sum(new_solution * value2_lst) + 1e-6)
    for _ in range(min(8, n_items // 3)):  # Increased number of replacement attempts
        i = random.randint(0, n_items - 1)
        j = random.randint(0, n_items - 1)
        if new_solution[i] == 1 and new_solution[j] == 0:
            if current_weight - weight_lst[i] + weight_lst[j] <= capacity:
                # Adaptive replacement criteria
